arduino.setup:
Serial.begin(9600);
pinMode(${D}, OUTPUT);
pinMode(${CLK}, OUTPUT);
pinMode(${S}, OUTPUT);
pinMode(${R}, OUTPUT);
pinMode(${Q}, INPUT);
pinMode(${Qbar}, INPUT);
Serial.println("D Flip-Flop (Set/Reset) ready");

arduino.loop:
Serial.println("--- S=0 R=0 ---");
digitalWrite(${S}, LOW);
digitalWrite(${R}, LOW);
for (int i=0; i<2; i++) {
  digitalWrite(${D}, i?HIGH:LOW);
  digitalWrite(${CLK}, LOW);
  delay(3);
  digitalWrite(${CLK}, HIGH);
  delay(3);
  Serial.print("D=");
  Serial.print(i);
  Serial.print(" Q=");
  Serial.print(digitalRead(${Q}));
  Serial.print(" Qbar=");
  Serial.println(digitalRead(${Qbar}));
  delay(300);
}
Serial.println("--- S=1 (set) ---");
digitalWrite(${S}, HIGH);
delay(10);
Serial.print("Q=");
Serial.print(digitalRead(${Q}));
Serial.print(" Qbar=");
Serial.println(digitalRead(${Qbar}));
digitalWrite(${S}, LOW);
Serial.println("--- R=1 (reset) ---");
digitalWrite(${R}, HIGH);
delay(10);
Serial.print("Q=");
Serial.print(digitalRead(${Q}));
Serial.print(" Qbar=");
Serial.println(digitalRead(${Qbar}));
digitalWrite(${R}, LOW);
delay(2000);
